/// <summary>
/// validateDelete
/// </summary>
/// <returns>Result</returns>
public boolean validateDelete()
{
    boolean ret;

    ret = super();

    METRetailerChannel referencedChannel;
    select firstonly RetailerChannelID from referencedChannel
        where   referencedChannel.CopyFromChannelID == this.RetailerChannelID;
    if(referencedChannel.RetailerChannelID)
    {
        ret = checkFailed(strFmt("@MET:RetailerChannelRefDeleteWarning",
            referencedChannel.RetailerChannelID));
    }
        
    return ret;
}

/// <summary>
/// Find retailer channel by channel ID
/// </summary>
/// <param name = "_channelID">_channelID</param>
/// <param name = "_forUpdate">_forUpdate</param>
/// <returns>Record</returns>
static public METRetailerChannel find(METRetailerChannelID _channelID, boolean _forUpdate = false)
{
    METRetailerChannel channel;
    channel.selectForUpdate(_forUpdate);
    select firstonly channel
        where   channel.RetailerChannelID == _channelID;
    return channel;
}

/// <summary>
/// Check if circular reference exists with CopyFromChannelID.
/// </summary>
/// <returns>True if circular reference detected</returns>
public boolean circularRefExists()
{
    METRetailerChannel  channel = this;
    Set                 channels = new Set(Types::String);
    while(channel)
    {
        if(channels.in(channel.RetailerChannelID))
        {
            return true;
        }
        channels.add(channel.RetailerChannelID);
        if(channel.CopyFromChannelID)
        {
            channel = METRetailerChannel::find(channel.CopyFromChannelID); 
        }
        else
        {
            break;
        }
    }
    return false;
}

/// <summary>
/// validateWrite
/// </summary>
/// <returns>Result</returns>
public boolean validateWrite()
{
    boolean ret;

    ret = super();

    if(this.CopyFromChannelID && this.CopyFromChannelID == this.RetailerChannelID)
    {
        ret = checkFailed("@MET:RetailerChannelCopyFromSelfSelected");
    }
    else if(this.circularRefExists())
    {
        ret = checkFailed("@MET:CircularReferenceDetected");
    }
    return ret;
}
